// THEORY GRID question bank.
// Every question here is original, written from The Highway Code and other GOV.UK
// guidance (Open Government Licence v3.0). None are copied from the DVSA revision bank.
// Format: [topic, question, [CORRECT, wrong, wrong, wrong], why, optional sign id]
// The correct answer is always first here; the game shuffles the order.

const TOPICS = {
  AL: "Alertness", AT: "Attitude", SV: "Safety & your vehicle", SM: "Safety margins",
  HA: "Hazard awareness", VU: "Vulnerable road users", OV: "Other vehicles",
  VH: "Vehicle handling", MW: "Motorway rules", RR: "Rules of the road",
  SG: "Road & traffic signs", DO: "Documents", IN: "Incidents & emergencies", LO: "Vehicle loading"
};

const ring = (inner) => `<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="46" fill="#fff" stroke="#d8001a" stroke-width="8"/>${inner}</svg>`;
const blue = (inner) => `<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="48" fill="#0a5cb8" stroke="#fff" stroke-width="2"/>${inner}</svg>`;
const tri = (inner) => `<svg viewBox="0 0 100 100"><path d="M50 8 L95 88 L5 88 Z" fill="#fff" stroke="#d8001a" stroke-width="8" stroke-linejoin="round"/>${inner}</svg>`;
const num = (n, fill) => `<text x="50" y="66" font-family="Arial,Helvetica,sans-serif" font-weight="bold" font-size="44" text-anchor="middle" fill="${fill}">${n}</text>`;

const SIGNS = {
  s30: ring(num(30, "#111")),
  min30: blue(num(30, "#fff")),
  nat: `<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="47" fill="#fff" stroke="#111" stroke-width="2"/><path d="M76 14 L86 24 L24 86 L14 76 Z" fill="#111"/></svg>`,
  noentry: `<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="48" fill="#d8001a" stroke="#fff" stroke-width="2"/><rect x="16" y="41" width="68" height="18" fill="#fff"/></svg>`,
  novehicles: ring(""),
  giveway: `<svg viewBox="0 0 100 100"><path d="M5 12 L95 12 L50 92 Z" fill="#fff" stroke="#d8001a" stroke-width="8" stroke-linejoin="round"/></svg>`,
  stop: `<svg viewBox="0 0 100 100"><path d="M31 4 H69 L96 31 V69 L69 96 H31 L4 69 V31 Z" fill="#d8001a" stroke="#fff" stroke-width="3"/><text x="50" y="61" font-family="Arial,Helvetica,sans-serif" font-weight="bold" font-size="29" text-anchor="middle" fill="#fff">STOP</text></svg>`,
  ahead: blue(`<path d="M50 16 L72 44 H58 V84 H42 V44 H28 Z" fill="#fff"/>`),
  nowaiting: `<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="44" fill="#0a5cb8" stroke="#d8001a" stroke-width="9"/><path d="M19 25 L25 19 L81 75 L75 81 Z" fill="#d8001a"/></svg>`,
  clearway: `<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="44" fill="#0a5cb8" stroke="#d8001a" stroke-width="9"/><path d="M19 25 L25 19 L81 75 L75 81 Z" fill="#d8001a"/><path d="M81 25 L75 19 L19 75 L25 81 Z" fill="#d8001a"/></svg>`,
  danger: tri(`<rect x="45" y="34" width="10" height="30" rx="3" fill="#111"/><circle cx="50" cy="75" r="6" fill="#111"/>`),
  crossroads: tri(`<rect x="45" y="36" width="10" height="44" fill="#111"/><rect x="30" y="54" width="40" height="8" fill="#111"/>`)
};

const QUESTIONS = [
// ---------- Alertness
["AL","What should you do before you signal to move off from the side of the road?",["Check your mirrors and look over your shoulder","Release the handbrake and start rolling","Sound your horn to warn others","Switch on your hazard warning lights"],"Mirrors first, then a look over your shoulder for the blind spot. You signal only once you know what is there, so the signal means something to the people who can see it."],
["AL","You start to feel sleepy on a long motorway drive. What should you do?",["Leave at the next exit or services and rest","Stop on the hard shoulder for a nap","Speed up to finish the journey sooner","Turn the radio up and keep going"],"Tiredness is a major cause of crashes. Leave the motorway at the next exit or service area and rest. The hard shoulder is for emergencies only, and noise or fresh air only help for a few minutes."],
["AL","How often does The Highway Code suggest taking a break on a long journey?",["At least 15 minutes every two hours","At least 5 minutes every four hours","Only when you need fuel","30 minutes every five hours"],"The Highway Code recommends a break of at least 15 minutes after every two hours of driving, to keep your concentration up."],
["AL","Your phone rings while you are driving. What should you do?",["Leave it and find a safe place to stop first","Answer it quickly and keep it short","Pull up on the hard shoulder to answer","Slow down and hold it lower so it is not seen"],"Holding a phone while driving is illegal and badly distracts you. Let it ring, and deal with it once you are parked somewhere safe and legal."],
["AL","What is a blind spot?",["An area your mirrors do not cover","An area lit by dipped headlights","The part of the road hidden by a hill","The space directly in front of the bonnet"],"Blind spots are areas around the car that you cannot see in the mirrors. That is why you look over your shoulder before moving off or changing lanes."],
["AL","You are using a sat nav and need to change the destination. What should you do?",["Stop in a safe place and then reprogram it","Ask it by hand while moving slowly","Do it at the next red traffic light","Do it on a straight, quiet stretch of road"],"Programming a sat nav takes your eyes and mind off the road. Stop somewhere safe first. Queuing at lights still counts as driving."],
["AL","Why should you use the mirrors before changing direction?",["To see how your move will affect traffic behind","To check the mirrors are adjusted properly","To check your passengers are belted in","To judge your speed more accurately"],"The mirror-signal-manoeuvre routine starts with mirrors so you know who is behind and beside you and how your move will affect them."],
["AL","You are driving at dusk on a dull day. Why should you switch on your lights?",["So that other road users can see you","So that your instrument panel is brighter","So that you can see road signs further off","So that the battery charges faster"],"In poor light, your lights are mostly about being seen. Other road users notice a lit vehicle much sooner."],
["AL","You miss your turning on a busy dual carriageway. What should you do?",["Carry on to the next exit and find another route","Stop and reverse back to the turning","Make a U-turn through a gap in the central reservation","Brake hard and turn from where you are"],"Never reverse or U-turn on a dual carriageway. Carry on, leave at the next junction and work your way back."],
["AL","Which of these is most likely to distract you while driving?",["Looking at a map or your phone screen","Checking your mirrors regularly","Keeping both hands on the wheel","Looking well ahead up the road"],"Anything that takes your eyes off the road, such as a map or a screen, is a distraction. Mirror checks and looking ahead are part of driving."],
["AL","Windscreen pillars can hide what from your view?",["Cyclists and pedestrians, especially at junctions","Only vehicles directly behind you","The dashboard warning lights","Road markings directly beneath the front of your own car"],"The pillars either side of the windscreen create blind spots large enough to hide a cyclist, motorcyclist or pedestrian. Move your head and look twice at junctions."],

// ---------- Attitude
["AT","A vehicle is following you far too closely. What should you do?",["Ease off and increase the gap in front of you","Brake sharply to warn the driver behind to drop back","Speed up to get away from it","Switch on your rear fog lights"],"If someone tailgates you, leave more room ahead. That gives you space to brake gently, which protects you both. Brake-testing or racing away only adds risk."],
["AT","What is the only reason to flash your headlights at another road user?",["To let them know that you are there","To tell them you are giving way","To thank them for letting you out","To warn them of a speed camera"],"The Highway Code says flashing headlights means one thing only: I am here. Do not use it to give instructions or to intimidate, and do not assume another driver's flash is an invitation."],
["AT","When may you sound your horn?",["To warn others of your presence","To claim your right of way","To greet someone you know","To hurry a slow driver along"],"The horn is a warning that you are there. It is not for showing annoyance or saying hello."],
["AT","In a built-up area, when must you NOT sound your horn (unless another road user is a danger)?",["Between 11:30 pm and 7 am","Between 9 pm and 6 am","Between 10 pm and 8 am","Between midnight and 5 am"],"You must not use the horn in a built-up area between 11:30 pm and 7:00 am, or while stationary, unless another road user poses a danger."],
["AT","A bus ahead is signalling to pull away from a bus stop. What should you do?",["Give way to it if you can do so safely","Speed up to get past before it moves","Sound your horn and keep going","Flash your headlights and overtake"],"The Highway Code asks you to give priority to buses pulling out, when it is safe. Watch for people getting off and crossing, too."],
["AT","You arrive at a crossroads with no signs or markings. Who has priority?",["Nobody has priority","The fastest vehicle","Traffic coming from the right","The largest vehicle"],"At an unmarked crossroads nobody has priority. Slow right down, look every way and be ready to stop."],
["AT","Why should you keep well back when following a large lorry?",["So you can see past it and the driver can see you","So that you use less fuel","So that your car is sheltered from crosswinds and spray","So that the lorry driver can reverse"],"Sitting close behind a lorry hides the road ahead from you and hides you from its mirrors. Dropping back opens up your view and gives you time to react."],
["AT","A driver pulls out in front of you at a junction and you have to brake. What should you do?",["Stay calm, drop back and let it go","Follow closely and sound your horn","Overtake as soon as possible to make a point","Flash your headlights repeatedly"],"Everybody makes mistakes. Reacting angrily makes a second incident more likely. Drop back and carry on."],
["AT","What does a flashing green beacon on a vehicle mean?",["A doctor on an emergency call","A slow-moving vehicle","A breakdown recovery vehicle","A police vehicle"],"Doctors answering an emergency call may use a green flashing beacon. Let them through when you safely can. Amber means slow-moving or recovery vehicles; blue is for the emergency services."],
["AT","You are in a one-way street and want to turn right. Where should you position?",["In the right-hand lane","In the left-hand lane","Just left of the centre line","In either lane, depending on traffic"],"In a one-way street there is no oncoming traffic, so you move to the right-hand side in good time to turn right."],
["AT","You are behind a learner driver who stalls at a junction. What should you do?",["Be patient and give them time","Sound your horn so they hurry up","Overtake immediately on the right","Rev your engine to let them know"],"Learners make mistakes, and pressure makes it worse. Wait calmly; everyone was a learner once."],
["AT","An emergency vehicle with blue lights is coming up behind you. What should you do?",["Pull over where it is safe and legal to let it pass","Stop immediately wherever you are, even on a bend or at a junction","Speed up to stay ahead of it","Mount the kerb straight away"],"Look for a safe place to let it through without breaking the law or endangering anyone. Avoid stopping on a bend, a brow or in the middle of a junction."],

// ---------- Safety & your vehicle
["SV","What is the legal minimum tread depth for car tyres?",["1.6 mm","1 mm","2.5 mm","4 mm"],"Car tyres must have at least 1.6 mm of tread across the central three-quarters of the breadth and around the whole circumference."],
["SV","When should you check your tyre pressures?",["When the tyres are cold","Straight after a long drive","Only when a tyre looks flat","After driving at high speed"],"Warm tyres give a falsely high reading. Check pressures cold, and do it regularly."],
["SV","What can under-inflated tyres affect?",["Braking and steering","The engine temperature","The oil pressure","The headlight aim"],"Soft tyres make steering heavy and braking worse, wear faster and use more fuel."],
["SV","A properly adjusted head restraint helps to reduce what?",["Neck injury in a collision","Tiredness on long journeys","Glare from vehicles behind","Travel sickness"],"The head restraint stops your head whipping back in a collision. It only works if it is set to the right height."],
["SV","What does a catalytic converter do?",["Reduces harmful exhaust emissions","Reduces engine noise","Improves fuel consumption at motorway speeds","Cools the exhaust gases"],"A catalytic converter treats the exhaust gases to cut the toxic and polluting emissions."],
["SV","Which driving style uses the most fuel?",["Harsh acceleration and late braking","Planning ahead and braking gently","Changing up through the gears early","Keeping to a steady speed"],"Rapid acceleration and heavy braking burn far more fuel. Looking ahead and being smooth saves fuel and wear."],
["SV","A red oil-pressure warning light comes on while you are driving. What should you do?",["Stop as soon as it is safe and check","Carry on to the next garage at speed","Ignore it if the engine sounds fine","Top up the coolant when you get home"],"Low oil pressure can wreck an engine in minutes. Stop when it is safe and investigate."],
["SV","Who is responsible for making sure a 10-year-old passenger wears a seat belt or child restraint?",["The driver","The child","The child's parent, wherever they are","The front-seat passenger"],"The driver is legally responsible for passengers under 14 wearing the right restraint. From 14 it is the passenger's own responsibility."],
["SV","Until when must a child normally use a suitable child car seat?",["Until 135 cm tall or 12 years old, whichever comes first","Until 100 cm tall or 5 years old","Until 150 cm tall or 16 years old","Until they can fasten an adult seat belt themselves without any help"],"Children must use the correct child restraint until they are 135 cm tall or reach their 12th birthday, whichever comes first."],
["SV","You want to fit a rear-facing baby seat in the front passenger seat. What must you do first?",["Deactivate the front passenger airbag","Slide the passenger seat fully forward on its runners","Recline the seat fully","Remove the head restraint"],"A rear-facing baby seat must never be used in a seat protected by an active frontal airbag. The airbag could seriously injure or kill the child."],
["SV","How should you dispose of used engine oil?",["Take it to a local authority recycling site","Pour it down a drain","Seal it in a bottle and put it in the household bin","Tip it on waste ground"],"Used oil is a pollutant. Take it, and old batteries, to a local authority site or a garage that accepts it."],
["SV","Your vehicle pulls to one side when you brake. What should you do?",["Have the brakes checked as soon as possible","Pump the brake pedal each time","Increase the tyre pressures","Use the handbrake at the same time to even out the braking"],"Pulling to one side usually means a brake fault. Get it looked at by a qualified mechanic straight away."],
["SV","Why should you switch off your engine if you will be stationary for some time?",["To cut emissions and save fuel","To let the battery recharge","To stop the tyres overheating","To keep the brakes cool"],"An idling engine burns fuel and pollutes for nothing. Switch off if you are going to be waiting more than a minute or two."],
["SV","What is most likely to waste fuel?",["Carrying an empty roof rack","Having correctly inflated tyres","Using higher gears where you can","Removing unneeded weight"],"A roof rack, even empty, adds wind resistance and so fuel use. Take it off when you are not using it."],
["SV","Before a long motorway journey, which is it sensible to check?",["Fuel, oil, water and tyres","The radio aerial","The spare key battery","The glovebox light"],"High speeds over long distances find weaknesses. Check fuel, oil, coolant, washer fluid, lights and tyres before you set off."],

// ---------- Safety margins
["SM","What is the typical overall stopping distance at 30 mph on a dry road?",["23 metres","12 metres","36 metres","53 metres"],"At 30 mph you travel about 9 metres while reacting and 14 metres while braking: 23 metres in all, roughly six car lengths."],
["SM","What is the typical overall stopping distance at 50 mph on a dry road?",["53 metres","36 metres","73 metres","96 metres"],"At 50 mph it is 15 metres thinking plus 38 metres braking: 53 metres, about thirteen car lengths."],
["SM","What is the typical overall stopping distance at 70 mph on a dry road?",["96 metres","53 metres","73 metres","120 metres"],"At 70 mph it is 21 metres thinking plus 75 metres braking: 96 metres, about twenty-four car lengths."],
["SM","What is the typical overall stopping distance at 20 mph on a dry road?",["12 metres","6 metres","23 metres","36 metres"],"At 20 mph it is 6 metres thinking plus 6 metres braking: 12 metres, about three car lengths."],
["SM","In good, dry conditions, what gap should you leave to the vehicle in front on a fast road?",["At least two seconds","At least half a second","One car length","One second"],"The two-second rule: as the vehicle ahead passes a fixed point, you should be able to say 'only a fool breaks the two-second rule' before you reach it."],
["SM","On a wet road, how much should you increase your following gap?",["At least double it","Leave it the same","Add one car length","Halve it"],"Tyres grip less on a wet road, so braking distances at least double. Make the two-second gap four seconds."],
["SM","On icy roads, braking distances can be how much longer?",["Up to ten times","Up to twice","Up to three times","Up to five times"],"On ice your tyres have very little grip, and it can take up to ten times as far to stop as on a dry road."],
["SM","Your car starts to aquaplane on a very wet road. What should you do?",["Ease off the accelerator and let it slow","Brake as hard as you can","Steer sharply from side to side","Change down quickly and accelerate"],"Aquaplaning means the tyres are riding on water and the steering feels light. Ease off gently and do not brake or steer suddenly until grip returns."],
["SM","What is the main benefit of anti-lock brakes (ABS)?",["You can steer while braking hard","You will always stop in a shorter distance","Your tyres wear more slowly","Your brakes will never overheat"],"ABS stops the wheels locking so you can keep steering while braking hard. It does not guarantee a shorter stopping distance, particularly on loose or slippery surfaces."],
["SM","You have just driven through a ford. What should you do first?",["Test your brakes","Stop and dry the brakes with a cloth","Switch on your hazard lights","Check your tyre pressures"],"Water can make brakes less effective. Test them gently as soon as it is safe; light braking as you drive helps to dry them."],
["SM","The rear of your car skids to the right. What should you do?",["Steer to the right, into the skid","Steer to the left, away from the skid","Brake firmly and hold the wheel still","Apply the handbrake"],"Steer into the skid: if the back slides right, steer right. Come off the accelerator and avoid braking harshly, which makes it worse."],
["SM","When might you need to keep a gap of more than two seconds, even in the dry?",["When a vehicle is tailgating you","When the road is empty","When the car in front is small","When you are in a 20 mph zone"],"With someone close behind, a bigger gap ahead lets you brake more gently, so they are less likely to run into you."],
["SM","What should you do when driving in fog?",["Use dipped headlights and slow down","Use full beam to see further","Follow the tail lights ahead closely","Keep up with the general traffic speed"],"In fog, use dipped headlights and drive at a speed that lets you stop within the distance you can see. Full beam reflects back, and tail lights ahead give false confidence."],
["SM","Which part of stopping distance is affected most by a tired driver?",["Thinking distance","Braking distance","Neither","Tyre grip"],"Thinking distance is how far you travel before you react. Tiredness, alcohol, drugs and distraction all make it longer."],
["SM","Where is the road most likely to be icy when the rest looks clear?",["On bridges and in shaded stretches","On the crown of the road in town","At junctions with traffic lights","Next to parked cars"],"Bridges and shaded parts freeze first and thaw last. Expect ice there even when the rest of the road seems fine."],

// ---------- Hazard awareness
["HA","A ball bounces into the road ahead of you. What should you do?",["Slow down and be ready to stop for a child","Swerve around the ball and carry on","Sound your horn and keep your speed","Drive over the ball to avoid swerving"],"A ball is often followed by a child who is watching the ball and not the traffic. Slow down and be ready to stop."],
["HA","You are passing a line of parked cars. What should you watch for?",["Doors opening or people stepping out","Empty parking spaces","Cars with their lights off","Cars parked facing the wrong way on your side"],"Parked cars hide pedestrians, especially children, and doors can swing open. Leave room and keep your speed down."],
["HA","Why is it dangerous to drive after taking some cold or hay-fever remedies?",["They can make you drowsy","They make your eyes more sensitive to light at night only","They always raise your blood alcohol","They affect your hearing"],"Some medicines cause drowsiness. Read the label or ask a pharmacist, and do not drive if you are affected."],
["HA","What is the safest amount of alcohol to drink before driving?",["None at all","One small drink","Whatever keeps you under the limit","Two units with food"],"Any alcohol affects judgement and reaction times, and how much puts you over the limit varies from person to person. The only safe amount is none."],
["HA","How does alcohol affect a driver?",["It gives false confidence and slows reactions","It sharpens concentration","It improves your judgement of speed and distance at night","It makes reactions faster"],"Alcohol slows your reactions, harms your judgement of speed and distance, and makes you feel more capable than you are."],
["HA","A cyclist ahead of you glances over their right shoulder. What does that probably mean?",["They may be about to move out or turn right","They want you to overtake now","They are about to pull in and stop on the left-hand side","They are checking their brakes"],"A look over the shoulder is often the first sign a cyclist is about to change position or turn. Hold back and give them room."],
["HA","Your view is blocked by parked vehicles as you emerge from a junction. What should you do?",["Edge forward slowly until you can see","Pull out quickly before anything comes","Sound your horn and go","Wait for someone to wave you out"],"Creep forward slowly so that you can see and be seen without committing to the road until you know it is clear."],
["HA","What does a vehicle with a flashing amber beacon usually mean?",["A slow-moving or stopped vehicle","An emergency vehicle","A doctor on call","A vehicle carrying dangerous goods"],"Amber beacons mark slow-moving vehicles, recovery vehicles and others that may be an obstruction. Approach with care."],
["HA","You see a pedestrian with a white stick that has a red band. What does it tell you?",["They are deaf and blind","They are blind only","They are deaf only","They are a road-crossing warden"],"A white stick with a red band, or a guide dog with a red and white harness, means the person is both deaf and blind. They will not hear you."],
["HA","You are driving towards a low winter sun and are dazzled. What should you do?",["Slow down, and stop if necessary","Close one eye and carry on","Speed up to get out of the glare","Put your headlights on full beam"],"If you cannot see properly, slow down or stop. Never carry on at a speed where you cannot stop in the distance you can see to be clear."],
["HA","Why should you not wear tinted glasses when driving at night?",["They reduce what you can see","They make oncoming lights flash","They are illegal on motorways","They make you look away from the road"],"Tinted lenses cut the light reaching your eyes, so you see less in the dark."],
["HA","An ice-cream van is parked ahead. What is the main hazard?",["Children running out from around it","Its chimes distracting you from the road ahead","It reversing suddenly","Litter on the road"],"Children are drawn to ice-cream vans and may run across without looking. Slow down and be ready to stop."],
["HA","You are approaching a bend on a narrow country road. What should you expect?",["Walkers, horses or a tractor just out of sight","A clear road ahead, as country roads carry little traffic","A higher speed limit","Street lighting after the bend"],"Country roads hide slow or vulnerable road users around bends. Drive at a speed that lets you stop in the distance you can see."],
["HA","When is a driver over 70 legally required to renew their licence?",["Every three years","Every year","Every five years","Every ten years"],"From 70, a driving licence must be renewed every three years, with a declaration about health and eyesight."],

// ---------- Vulnerable road users
["VU","How much room should you leave when overtaking a cyclist at up to 30 mph?",["At least 1.5 metres","At least 0.5 metres","About a door's width","Whatever keeps you on your side of the line"],"The Highway Code says leave at least 1.5 metres when passing cyclists at speeds up to 30 mph, and more room at higher speeds."],
["VU","How should you pass a horse rider?",["At under 10 mph, leaving at least 2 metres","At normal speed with a short horn warning","Quickly, to spend less time alongside","Close in, so oncoming traffic can pass"],"Horses can be startled by speed and noise. Pass at no more than 10 mph and leave at least 2 metres. Do not sound the horn or rev the engine."],
["VU","You are turning left into a side road and a pedestrian is waiting to cross it. What should you do?",["Give way to the pedestrian","Carry on, as you are on the road","Sound your horn to warn them","Wave them back onto the pavement"],"Since 2022 The Highway Code says you should give way to pedestrians crossing or waiting to cross a road that you are turning into or out of."],
["VU","In the hierarchy of road users, who carries the greatest responsibility to reduce danger?",["Those in charge of the vehicles that can do most harm","Pedestrians, because they are slowest","Cyclists, because they are hard to see","Everybody equally, whatever they drive, ride or walk with on the road"],"The hierarchy puts those most at risk at the top. Drivers of large vehicles, then cars and motorcycles, bear the greatest responsibility to look after others."],
["VU","What is the 'Dutch Reach'?",["Opening your door with the hand furthest from it","Signalling with your arm out of the window","Leaning forward to see past the pillar","Reaching across to unlock the passenger door"],"Using the far hand turns your body, so you naturally look over your shoulder and are less likely to open the door into a cyclist or motorcyclist."],
["VU","A school crossing patrol steps out and shows the stop sign. What must you do?",["Stop and wait until they are clear","Slow down and steer around them","Carry on if no children are in the road","Sound your horn and proceed carefully"],"You must stop when a school crossing patrol shows the stop-for-children sign. It is the law."],
["VU","You are turning left and a cyclist is riding along your nearside. What should you do?",["Hold back and let the cyclist go first","Overtake and turn in front of them","Move closer to the kerb to block them","Sound your horn and turn"],"Do not cut across cyclists going ahead when you turn. Wait behind them and turn once they are clear."],
["VU","Why should you look carefully for motorcyclists at junctions?",["They are smaller and harder to see","They always travel faster than cars","They are not allowed to use dipped lights","They have priority at junctions"],"A motorcycle's narrow outline is easily hidden by a pillar, a sign or another vehicle. Look, then look again, before pulling out."],
["VU","Pedestrians are walking on a country road with no pavement. Which side should they normally be on?",["The right, facing oncoming traffic","The left, with their backs to traffic","Either side, in the middle of the lane","The left, in single file only at night"],"With no pavement, pedestrians are advised to walk on the right so they can see traffic coming towards them. Expect to meet them on your side of the road."],
["VU","At a pelican crossing, the amber light is flashing. What does it mean?",["Give way to pedestrians still on the crossing","Stop and wait for green whatever happens","Pedestrians must not start or finish crossing","Accelerate to clear the crossing"],"Flashing amber means you must give way to anyone on the crossing. If it is clear, you may go."],
["VU","Who can use a toucan crossing?",["Pedestrians and cyclists together","Pedestrians only; cyclists must get off and walk","Horse riders only","Cyclists only"],"On a toucan crossing 'two can' cross: cyclists are allowed to ride across alongside pedestrians."],
["VU","A cyclist is going round a roundabout in the left-hand lane. What should you bear in mind?",["They may be going all the way round to turn right","They must be leaving at the first exit, as that lane is for it","They have to give way to you","They will always signal first"],"Cyclists and horse riders may stay in the left lane whichever exit they want. Give them room and do not cut across them."],
["VU","You are at a zebra crossing and someone is waiting on the pavement to cross. What should you do?",["Stop and let them cross","Wave them across","Carry on, as they are not yet on the crossing","Sound your horn and continue"],"Give way to people waiting at a zebra crossing, and you must give way once they have stepped onto it. Do not wave them across; another vehicle may not have stopped."],
["VU","Why should you allow extra room when passing a motorcyclist on a windy day?",["They can be blown off course","They are likely to speed up","They ride closer to the kerb in wind","Their brakes work less well in wind"],"Gusts can move a motorcycle or bicycle sideways suddenly, especially past gaps and large vehicles. Leave extra space."],
["VU","A mobility scooter is using a dual carriageway. What will help you recognise it?",["A flashing amber beacon","A flashing blue beacon","A red flag on a pole","Hazard lights and a horn"],"Powered wheelchairs and scooters, limited to 8 mph, should use a flashing amber beacon on dual carriageways with a limit above 50 mph."],

// ---------- Other types of vehicle
["OV","You are behind a long lorry that moves to the right before a left turn. What should you do?",["Stay back and let it complete the turn","Pass it on the left while there is room","Sound your horn so it moves over","Overtake it on the right"],"Long vehicles often need to swing out to get round a corner. Never go up the inside; hold back and give it room."],
["OV","Why is it harder to overtake a large lorry than a car?",["It takes longer to get past","Lorries always speed up when overtaken","Lorries have no mirrors on the right","You must use your hazard lights to do it"],"A lorry is long, so you spend more time on the other side of the road. Make sure you have much more clear road than you would need for a car."],
["OV","In wet weather you are following a lorry that is throwing up spray. What should you do?",["Drop back until you can see clearly","Move closer so you are under the spray","Switch to full beam","Overtake as quickly as you can"],"Spray cuts your vision badly. Drop back to where you can see, and use dipped headlights."],
["OV","Why should you take extra care near trams?",["They cannot steer to avoid you","They always have to give way to cars","They are slower than cyclists","They only run at night"],"Trams run on rails, cannot swerve, and are quiet and quick. Do not block their path."],
["OV","Which vehicle is most likely to be affected by strong crosswinds?",["A high-sided van or a motorcycle","A low sports car","A heavy saloon car","An estate car with the windows closed"],"High-sided vehicles, motorcycles, cyclists and caravans are blown about most. Give them extra room, especially on exposed roads and bridges."],
["OV","A bus has stopped at a bus stop ahead. What should you look out for?",["People crossing from in front of or behind the bus","The bus reversing back towards you to straighten up at the stop","Passengers waving you past","The bus switching its lights off"],"People getting off may step out from behind or in front of the bus where you cannot see them. Slow down and be ready to stop."],
["OV","You are waiting to turn right out of a junction and a lorry on the main road is signalling left to turn in. Why wait?",["A vehicle may be overtaking the lorry, hidden from you","The lorry has priority to turn right","The lorry will block your exit for good","Lorries are not allowed to turn left into a side road while you wait"],"The lorry hides anything overtaking it. Wait until it has turned in and you can see the road is clear."],
["OV","At a mini-roundabout a long vehicle may do what?",["Drive over the central marking","Stop in the centre to let traffic past","Reverse to get round","Go round it the wrong way"],"Long vehicles may be physically unable to get round a mini-roundabout without crossing the centre. Give them space."],

// ---------- Vehicle handling
["VH","When may you use front and rear fog lights?",["When visibility is below 100 metres","Whenever it is raining","Whenever it is dark","When visibility is below 500 metres"],"Fog lights are for seriously reduced visibility, generally when you cannot see more than 100 metres. You must switch them off when visibility improves."],
["VH","Why must you switch off rear fog lights when the fog clears?",["They dazzle the drivers behind you","They drain the battery in minutes","They make the car harder to steer","They stop the indicators working"],"Rear fog lights are very bright. In clear conditions they dazzle following drivers and make your brake lights harder to notice."],
["VH","You are going down a long, steep hill. How can you keep your speed under control?",["Select a lower gear and brake gently","Select neutral and use the brakes","Keep the clutch down and steer carefully","Use the handbrake on and off"],"A lower gear gives engine braking, which holds your speed without overheating the brakes. Coasting takes that control away."],
["VH","What does 'coasting' mean, and why is it wrong?",["Rolling in neutral or clutch down, which reduces control","Driving near the kerb, which damages tyres","Driving in top gear, which wastes fuel","Braking gently downhill, which overheats the brakes"],"Coasting means travelling with the clutch down or in neutral. You lose engine braking, speed can build quickly, and steering and braking are less effective."],
["VH","You are driving at night on full beam and a vehicle comes towards you. What should you do?",["Dip your headlights","Flash your headlights","Switch to sidelights","Keep full beam until it has passed"],"Dip your lights so you do not dazzle the oncoming driver. The same applies when you are following another vehicle."],
["VH","You are dazzled by the headlights of an oncoming vehicle at night. What should you do?",["Slow down, and stop if you need to","Flash your full beam back","Look straight at the lights to adjust","Swerve towards the verge"],"If you are dazzled, slow down or stop. Do not retaliate with your own lights."],
["VH","It rains after a long dry, hot spell. Why take extra care?",["The road surface can be unusually slippery","The tyres will overheat","Your brakes will work too well","The rain makes road signs unreadable"],"Oil and rubber build up on the road in dry weather. The first rain mixes with them and makes the surface very slippery."],
["VH","How should you drive on snow?",["In the highest gear you can, with gentle controls","In first gear with high revs","With firm braking every few seconds to test how much grip there is","With the handbrake partly on"],"A high gear and gentle acceleration reduce wheelspin. Brake, steer and accelerate smoothly, and leave a much bigger gap."],
["VH","You are overtaking a lorry on a motorway in a strong crosswind. What should you expect?",["A sudden gust as you clear the front of the lorry","Better grip while alongside it","The lorry to slow down for you","Your steering to become heavier throughout"],"The lorry shelters you while you are alongside. As you pass the front, the wind hits you again, so keep a firm grip on the wheel."],
["VH","You have to park on the road at night where the limit is over 30 mph. What must you do?",["Leave your parking lights on","Park facing the traffic","Leave your hazard lights on","Leave dipped headlights on"],"On a road with a speed limit above 30 mph, a parked vehicle must show parking lights at night. You must also park facing the direction of the traffic flow."],
["VH","How do traffic-calming measures such as road humps help?",["They reduce traffic speed","They shorten journey times","They improve fuel economy","They reduce tyre wear"],"Humps, chicanes and narrowings are there to slow traffic where there are vulnerable road users. Keep your speed down the whole way through."],
["VH","When should you use the right-hand lane of a two-lane dual carriageway?",["For overtaking or turning right","For driving at the speed limit","For any long journey","When the left lane has lorries in it"],"Keep to the left-hand lane. The right-hand lane is for overtaking or turning right, and you should move back once it is safe."],

// ---------- Motorway rules
["MW","What is the national speed limit for a car on a motorway?",["70 mph","60 mph","80 mph","50 mph"],"The national limit for cars and motorcycles on motorways is 70 mph, unless signs show a lower limit."],
["MW","What is the speed limit for a car towing a caravan on a motorway?",["60 mph","50 mph","70 mph","40 mph"],"Cars towing a caravan or trailer are limited to 60 mph on motorways and dual carriageways, and 50 mph on single carriageways."],
["MW","You are towing a trailer on a motorway with three lanes. Which lane must you NOT use?",["The right-hand lane","The left-hand lane","The middle lane","Any lane next to a lorry"],"Vehicles towing a trailer must not use the right-hand lane of a motorway with three or more lanes, unless lanes are closed."],
["MW","You are joining a motorway from a slip road. Who has priority?",["Traffic already on the motorway","Traffic joining from the slip road","Whichever vehicle is faster","Larger vehicles only"],"Give way to traffic already on the motorway. Use the slip road to match your speed and join where there is a safe gap."],
["MW","Which lane should you normally use on a clear three-lane motorway?",["The left-hand lane","The middle lane","The right-hand lane","Any lane you like"],"Keep to the left-hand lane unless you are overtaking, and return to it when it is safe. Sitting in the middle lane is poor lane discipline and can be an offence."],
["MW","A red X is showing above your lane on a motorway. What does it mean?",["The lane is closed: you must not drive in it","The lane is for buses only","There is a speed camera on the gantry above that lane","The hard shoulder is open"],"A red X means the lane is closed, often because of an incident or people working ahead. Move out of it promptly and safely. Ignoring it is an offence."],
["MW","What colour are the reflective studs between a motorway and its slip road?",["Green","Red","Amber","White"],"Green studs mark the edge of the main carriageway at slip roads and lay-bys."],
["MW","What colour are the reflective studs along the left edge of a motorway?",["Red","Green","White","Amber"],"Red studs mark the left edge of the carriageway. White separate the lanes, and amber run along the central reservation."],
["MW","What colour are the reflective studs alongside the central reservation of a motorway?",["Amber","Red","Green","White"],"Amber studs mark the right-hand edge, next to the central reservation. Red are on the left edge and white between lanes."],
["MW","Your car breaks down on a motorway and you reach the hard shoulder. Where should you wait?",["Behind the barrier, away from the traffic","In the car with your seat belt on","Behind the car on the hard shoulder","In front of the car, to flag down help"],"Leave by the left-hand door and wait behind the safety barrier, well away from traffic. Many people have been killed on hard shoulders."],
["MW","How do you find the nearest emergency telephone on a motorway?",["Follow the arrows on the marker posts","Walk against the flow of traffic","Cross to the central reservation","Look for the next blue sign with a P"],"The small marker posts at the edge of the hard shoulder have arrows pointing to the nearest emergency telephone. Never cross the carriageway."],
["MW","What are emergency areas on a motorway for?",["Stopping in an emergency or breakdown","Short rest breaks","Using a mobile phone","Letting faster traffic pass when you are towing"],"Emergency areas are marked with blue signs with an orange SOS telephone symbol. Use them only in an emergency or breakdown."],
["MW","A speed limit is shown inside a red circle on a motorway gantry. What does it mean?",["It is a mandatory maximum speed limit","It is an advisory speed for bad weather","It applies to lorries only","It is the minimum speed for that lane"],"Limits shown in a red ring are compulsory and enforced, just like any other speed limit sign."],
["MW","Who is NOT allowed on a motorway?",["Riders of motorcycles under 50 cc","Drivers towing a caravan","Drivers over 70 years old","Riders of motorcycles over 125 cc"],"Motorways are off limits to pedestrians, cyclists, horse riders, motorcycles under 50 cc, and certain slow vehicles."],
["MW","Can a learner car driver have lessons on a motorway?",["Yes, with an approved instructor in a dual-control car","No, not until they pass the practical test","Yes, with any full licence holder over 21 sitting beside them","Yes, but only outside the rush hour"],"Since 2018 learner drivers in England, Scotland and Wales may drive on motorways with an approved driving instructor in a car fitted with dual controls."],
["MW","What do the countdown markers before a motorway exit show?",["Each bar is 100 yards to the start of the slip road","Each bar is a quarter of a mile to the end of the motorway","The number of lanes on the exit","The speed limit on the slip road"],"The markers have three, two and then one bar, at 300, 200 and 100 yards before the deceleration lane begins."],
["MW","When may you use the hard shoulder of a motorway?",["In an emergency, or when signs direct you to","To overtake slow traffic when all the other lanes are queuing","To take a phone call","To rest when you are tired"],"The hard shoulder is for emergencies and breakdowns only, unless signs show it is open as a running lane."],

// ---------- Rules of the road
["RR","What is the national speed limit for a car on a single carriageway road?",["60 mph","50 mph","70 mph","40 mph"],"On a single carriageway the national limit for cars and motorcycles is 60 mph. On dual carriageways and motorways it is 70 mph."],
["RR","What is the national speed limit for a car on a dual carriageway?",["70 mph","60 mph","50 mph","80 mph"],"Cars and motorcycles may do up to 70 mph on a dual carriageway unless signs say otherwise."],
["RR","In England, there are street lights but no speed limit signs. What is the limit usually?",["30 mph","20 mph","40 mph","60 mph"],"A system of street lighting normally means a 30 mph limit in England unless signs say otherwise. In Wales the default on such roads is 20 mph."],
["RR","When may you enter a box junction if your exit is not clear?",["When turning right and only oncoming traffic stops you","When you are in a queue of slow traffic","When the lights are green","When there are fewer than two cars ahead of you inside the box"],"You must not enter a box junction unless your exit is clear. The exception is waiting to turn right when only oncoming traffic, or others turning right, is in your way."],
["RR","How close to a junction may you park?",["No closer than 10 metres","No closer than 2 metres","No closer than 5 metres","As close as you like if you are not on yellow lines"],"Do not park within 10 metres (32 feet) of a junction, except in an authorised parking space. It blocks the view for everyone using it."],
["RR","What do double yellow lines along the edge of the road mean?",["No waiting at any time","No stopping at any time, for any reason","No waiting during the working day","Parking for permit holders only"],"Double yellow lines mean no waiting at any time, though you may usually stop briefly to load or let passengers in and out unless other signs forbid it."],
["RR","What do double red lines mean on a red route?",["No stopping at any time","No waiting between 7 am and 7 pm","Loading only","Buses and taxis only"],"On a red route, double red lines mean no stopping at all, at any time, not even to drop someone off."],
["RR","The double white line in the middle of the road is solid on your side. When may you cross it?",["To pass a cyclist or horse doing 10 mph or less","To overtake any vehicle doing under 30 mph","Whenever the road ahead looks clear","Only outside built-up areas"],"With a solid line nearest you, you may cross only to turn into premises or a side road, pass a stationary vehicle, or overtake a cycle, horse or road maintenance vehicle travelling at 10 mph or less, when it is safe."],
["RR","When may you overtake on the left?",["When traffic is in slow queues and your queue is moving faster","Whenever the left lane is empty","When the vehicle ahead is doing under the limit and will not move over","On any motorway at night"],"You may pass on the left when the vehicle ahead is signalling to turn right, or when traffic is moving in queues and the lane on the right is slower. Do not weave between lanes to do it."],
["RR","At traffic lights, what does red and amber together mean?",["Stop: do not go until green shows","Go if the way is clear","Give way to pedestrians, then go","The lights are faulty"],"Red and amber together still means stop. It tells you green is about to show; do not move off until it does."],
["RR","What does a steady amber traffic light mean?",["Stop, unless it is unsafe to do so","Speed up to clear the junction","Go, but give way to pedestrians","Get ready to move off"],"Amber means stop. You may go on only if you have already crossed the stop line or are so close that stopping might cause a collision."],
["RR","The traffic lights at a junction are not working. What should you do?",["Treat it as an unmarked junction","Assume you have priority on the wider road","Wait until the lights are repaired","Follow the vehicle in front"],"If lights are out, nobody has priority. Treat it like an unmarked junction and go carefully."],
["RR","Who has priority at a roundabout, unless signs or markings say otherwise?",["Traffic coming from your right","Traffic coming from your left","The vehicle travelling fastest","Whoever arrives first"],"Give priority to traffic approaching from your right unless road markings or signals tell you otherwise."],
["RR","You are taking the first exit, to the left, at a roundabout. How should you signal?",["Signal left on approach","Signal right, then left","Do not signal at all","Signal left only once you are on the roundabout"],"For the first exit, signal left as you approach and keep to the left."],
["RR","When may you drive in a bus lane?",["Outside its hours of operation","Whenever no bus is in sight","When you are turning right ahead","When traffic in your lane has stopped"],"Check the signs. Outside the times shown, or if no times are shown and signs permit, other traffic may use the lane. If no times are shown, it applies 24 hours a day."],
["RR","Where must you never park?",["On the zigzag lines at a pedestrian crossing","In a marked bay outside a shop","On a road with a single broken white line","In a lay-by on a rural road"],"You must not park on a crossing or the zigzags either side. It hides pedestrians from drivers and drivers from pedestrians."],
["RR","When may you reverse from a side road into a main road?",["You should not; avoid it whenever possible","When traffic on the main road is light","When someone guides you","When you have your hazard lights on"],"The Highway Code says do not reverse from a side road into a main road. If you need to reverse, reverse into the side road."],
["RR","At a level crossing, the red lights keep flashing after a train has passed. What should you do?",["Keep waiting: another train is coming","Drive across carefully","Phone the signal operator at once","Reverse away from the crossing"],"If the lights continue to flash, another train is approaching. Wait until they go out and the barriers rise."],
["RR","What do zigzag yellow lines outside a school mean?",["Do not wait or park here, even to drop off","Parents may park to collect children","Parking for teachers only","A 20 mph limit applies"],"School keep-clear markings must be left free so that children crossing can see and be seen. Do not stop there even briefly."],
["RR","An area of white diagonal stripes is bordered by a solid white line. When may you enter it?",["Only in an emergency","Whenever it is safe","To overtake slow traffic","To wait to turn right"],"Hatched areas with a solid edge must not be entered except in an emergency. If the edge is broken, you may enter only when necessary and safe."],
["RR","You want to turn right from a main road and an oncoming car also wants to turn right. What is the usual way to do it?",["Pass offside to offside","Whoever is larger goes first","Both stop and wait for a signal","Always pass nearside to nearside"],"Turning offside to offside (right side to right side) gives both drivers a clear view of oncoming traffic. Markings or layout sometimes require nearside to nearside instead."],

// ---------- Road & traffic signs
["SG","What shape are traffic signs that give orders?",["Circular","Triangular","Rectangular","Diamond"],"Circles give orders: red rings prohibit, blue circles instruct. Triangles warn and rectangles inform."],
["SG","What shape are most warning signs?",["Triangular","Circular","Rectangular","Octagonal"],"Warning signs are mostly triangles with a red border. Circles give orders and rectangles give information."],
["SG","What does a circular sign with a blue background tell you?",["Something you must do","Something you must not do","A hazard ahead","Tourist information"],"Blue circles give a positive instruction, such as turn left or minimum speed. Red rings tell you what you must not do."],
["SG","What does this sign mean?",["National speed limit applies","No entry","End of motorway regulations ahead","No waiting"],"A white disc with a black diagonal stripe means the national speed limit applies: for a car, 60 mph on single carriageways and 70 mph on dual carriageways and motorways.","nat"],
["SG","What does this sign mean?",["No entry for vehicles","No stopping","Road closed to pedestrians","One-way street ahead"],"A red disc with a white horizontal bar means no entry for vehicular traffic.","noentry"],
["SG","What does this sign mean?",["Maximum speed 30 mph","Minimum speed 30 mph","30 metres to a hazard","Route number 30"],"A number in a red ring is a maximum speed limit. It is a limit and not a target.","s30"],
["SG","What does this sign mean?",["Minimum speed 30 mph","Maximum speed 30 mph","End of a 30 mph limit","Parking for 30 minutes"],"A number on a blue circle is a minimum speed. You should keep to at least that speed unless it is unsafe to do so.","min30"],
["SG","What does this sign mean?",["Give way","Stop","No overtaking","Road narrows"],"The upside-down triangle is the give way sign: give way to traffic on the major road. Its unique shape means you can recognise it even from behind or covered in snow.","giveway"],
["SG","Why is the stop sign an octagon?",["So it is recognisable even under snow","So it reflects headlights better","Because it is a temporary sign","Because it only applies to large vehicles"],"The eight-sided shape is unique to the stop sign, so you can tell what it is even when the face is obscured. You must stop at the line.","stop"],
["SG","What does this sign mean?",["No vehicles except bicycles being pushed","No speed limit","End of all speed limits and parking restrictions","No pedestrians"],"An empty red ring means no vehicles at all, except bicycles being pushed by hand.","novehicles"],
["SG","What does this sign mean?",["Ahead only","One-way street","Motorway ahead","Keep left"],"A white arrow pointing up on a blue circle means you must go straight ahead.","ahead"],
["SG","What does this sign mean?",["No waiting","No stopping","No entry","No overtaking"],"A blue disc with a red ring and one red diagonal means no waiting. With a red cross it would mean no stopping.","nowaiting"],
["SG","What does this sign mean?",["No stopping (clearway)","No waiting","No through road","Level crossing ahead"],"A red cross on a blue disc is the clearway sign: you must not stop on the carriageway at all, even to drop someone off.","clearway"],
["SG","What does this sign warn of?",["Crossroads ahead","A hospital ahead","A level crossing ahead","A T-junction ahead"],"A cross inside a warning triangle means crossroads ahead.","crossroads"],
["SG","What does this sign mean?",["Other danger ahead","Emergency telephone","Information point","Accident black spot only"],"An exclamation mark in a triangle warns of some other danger. A plate beneath it usually says what the hazard is.","danger"],
["SG","What colour are the direction signs on a motorway?",["Blue with white lettering","Green with white lettering","White with black lettering","Brown with white lettering"],"Motorway signs are blue. Primary routes are green, other routes are white with a black border, and tourist attractions are brown."],
["SG","What do brown direction signs show?",["Tourist attractions","Diversion routes","Primary routes","Lorry routes"],"Brown signs guide you to tourist attractions and facilities."],
["SG","What colour are direction signs on a primary route (not a motorway)?",["Green","Blue","Brown","Yellow"],"Primary route signs have a green background with white lettering and yellow route numbers."],
["SG","At a junction there is a stop sign and a solid white line across the road. What must you do?",["Stop at the line, even if the road is clear","Slow down and go if it is clear","Give way only to traffic from the right","Stop only if other traffic is coming"],"A stop sign with a solid line means you must come to a complete stop and wait for a safe gap, every time."],
["SG","What does a broken white line across your half of the road at a junction mean?",["Give way to traffic on the major road","You must always stop, even when the major road is clear","You have priority","No entry"],"A broken line across the road at a junction is a give way line. You need not stop if the way is clear."],
["SG","The centre line on the road changes to long white lines with short gaps. What does that tell you?",["A hazard is ahead","Overtaking is encouraged","The speed limit is rising","A motorway is starting"],"Longer lines with shorter gaps are hazard warning lines. Do not cross them unless you can see the road is clear well ahead."],
["SG","A police officer is directing traffic and holds an arm up, palm towards you. What must you do?",["Stop","Turn left","Slow down and pass","Go ahead"],"Signals from police and traffic officers overrule signs and lights. A raised palm facing you means stop."],
["SG","You see a green filter arrow lit at traffic lights. What does it mean?",["You may go in the direction of the arrow","You must wait for the full green","Pedestrians have priority across your path","All lanes may go"],"A green arrow lets you go in that direction if the way is clear, whatever the other lights are showing."],
["SG","What does a yellow rectangular sign with black symbols at roadworks usually show?",["A temporary diversion or lane arrangement","A permanent speed limit","A tourist route","A motorway service area with fuel and food available"],"Temporary signs for roadworks and diversions are yellow with black lettering or symbols."],

// ---------- Documents
["DO","What is the minimum insurance cover you need to drive on a public road?",["Third party","Fully comprehensive","Third party, fire and theft","Personal accident"],"Third-party cover is the legal minimum. It pays for injury and damage to others but not for damage to your own vehicle."],
["DO","In Great Britain, when must a new car first have an MOT test?",["When it is three years old","When it is one year old","When it is five years old","When it changes owner"],"Cars need their first MOT at three years old in Great Britain and every year after that."],
["DO","A new driver gets six or more penalty points within two years of passing. What happens?",["Their licence is revoked and they must retake both tests","They get a written warning","They pay a larger fine and keep the licence, with a warning letter","They are banned for one month only"],"Under the New Drivers Act, six points in the first two years means the licence is revoked. You go back to being a learner and must pass the theory and practical tests again."],
["DO","What is the standard penalty for using a hand-held phone while driving?",["Six penalty points and a £200 fine","Three penalty points and a £60 fine","A verbal warning","A £30 fixed penalty only"],"It is six points and a £200 fine. For someone who passed within the last two years, that alone is enough to lose their licence."],
["DO","What is a SORN?",["A statement that a vehicle is kept off the road","A certificate proving a vehicle is roadworthy","A type of insurance cover note","A permit to drive without tax"],"A Statutory Off Road Notification tells DVLA the vehicle is not being used or kept on a public road, so it does not need tax or insurance."],
["DO","Which document shows who the registered keeper of a vehicle is?",["The V5C registration certificate","The MOT certificate","The insurance certificate","The driving licence"],"The V5C, or logbook, records the registered keeper. You must tell DVLA when the keeper, address or vehicle details change."],
["DO","Who must supervise a learner driver in a car?",["Someone at least 21 who has held a full licence for three years","Anyone who holds a full licence and is insured to drive the car themselves","Someone at least 18 with one year's licence","Only an approved instructor"],"A supervisor must be at least 21 and have held a full licence for that type of vehicle for at least three years."],
["DO","What eyesight standard must you meet to drive?",["Read a number plate from 20 metres","Read a number plate from 10 metres","Read a road sign from 100 metres","Read a number plate from 50 metres"],"You must be able to read a modern number plate from 20 metres, with glasses or contact lenses if you need them. If you need them for that, you must wear them every time you drive."],
["DO","When must you tell DVLA about your health?",["When a condition could affect your driving","Only when you renew at 70","Every time you see a doctor","Never; your doctor is required to tell them for you"],"You must tell DVLA about any medical condition that may affect your driving, or if an existing one gets worse. Not doing so can mean a fine of up to £1,000."],
["DO","How often must a photocard driving licence be renewed?",["Every 10 years","Every 3 years","Every 5 years","Never, it lasts until you are 70"],"The photo on a photocard licence must be renewed every 10 years, until you are 70."],
["DO","The police ask to see your documents and you do not have them with you. What can you do?",["Produce them at a police station within 7 days","Post them within 28 days","Nothing; you will be given a fixed penalty on the spot instead","Email photographs within 24 hours"],"You may be asked to produce your licence, insurance certificate and MOT certificate at a police station within seven days."],
["DO","What is the 'excess' on a car insurance policy?",["The amount you pay towards any claim","The extra charge for young drivers","The no-claims discount","The cost of adding a second driver"],"The excess is the first part of any claim that you pay yourself, for example the first £250."],
["DO","What is the legal drink-drive limit in England and Wales, measured in breath?",["35 micrograms per 100 ml","22 micrograms per 100 ml","50 micrograms per 100 ml","80 micrograms per 100 ml"],"In England, Wales and Northern Ireland the limit is 35 micrograms of alcohol per 100 ml of breath (80 mg per 100 ml of blood). Scotland's limit is lower at 22. The safest amount is none."],
["DO","How many questions must you get right to pass the car theory test's multiple-choice part?",["43 out of 50","35 out of 50","40 out of 50","45 out of 50"],"You need 43 out of 50 in 57 minutes, and you must also pass the hazard perception part with 44 out of 75."],

// ---------- Incidents & emergencies
["IN","You are first at the scene of a crash. What should you do first?",["Warn other traffic and make the scene safe","Move all the casualties to the roadside","Give the casualties a hot drink","Clear the debris off the road"],"Further collisions are the first danger. Use hazard lights, get engines switched off, and call the emergency services. Do not move casualties unless they are in danger."],
["IN","A casualty in a crashed car is conscious and not in danger from fire or traffic. What should you do?",["Keep them still until help arrives","Lift them out and lay them flat","Help them walk around","Give them something to drink"],"Moving someone could worsen a spinal injury. Keep them still, warm and reassured unless they are in further danger."],
["IN","An injured motorcyclist is lying in the road. Should you remove their helmet?",["No, unless it is essential","Yes, always, as soon as you can","Yes, if they ask for a drink","Yes, to check for head wounds"],"Removing a helmet can make a neck injury much worse. Leave it on unless it is essential to keep the airway clear."],
["IN","A casualty is not breathing. At what rate should you give chest compressions?",["100 to 120 a minute","20 to 30 a minute","50 to 60 a minute","200 a minute"],"Push down 5 to 6 cm in the centre of the chest at a rate of 100 to 120 compressions a minute, about two a second."],
["IN","Someone has a burn. What should you do?",["Cool it with clean, cool water","Put cream or ointment on it","Burst any blisters","Pull off anything stuck to it"],"Douse the burn with clean, cool, non-toxic liquid. Do not remove anything stuck to the burn and do not apply creams."],
["IN","A casualty is bleeding heavily from an arm, with nothing stuck in the wound. What should you do?",["Apply firm pressure to the wound","Give them a warm drink","Leave the wound open to the air","Lower the arm below the heart and wait"],"Press firmly over the wound, with clean material if you have it, to slow the bleeding until help arrives."],
["IN","How far behind your broken-down car should you place a warning triangle on an ordinary road?",["At least 45 metres","At least 5 metres","At least 10 metres","At least 100 metres"],"Put the triangle at least 45 metres (147 feet) behind the vehicle on the same side of the road. Never use one on a motorway."],
["IN","Should you put out a warning triangle if you break down on a motorway?",["No, never on a motorway","Yes, 45 metres behind the car","Yes, 150 metres behind the car","Yes, but only at night"],"It is too dangerous to walk along a motorway placing a triangle. Get out on the left and wait behind the barrier."],
["IN","You are in a collision that causes damage, and you cannot exchange details with anyone. What must you do?",["Report it to the police within 24 hours","Report it to your insurer within a month","Nothing, if no one was hurt","Leave a note and do nothing more"],"You must stop. If you do not give your name and address at the time, you must report the collision to the police as soon as reasonably practicable, and in any case within 24 hours."],
["IN","Your car catches fire in a tunnel and you cannot drive it out. What should you do?",["Stop, switch on hazard lights and leave by the nearest exit","Stay in the car with the windows closed until the fire service arrives","Reverse out of the tunnel","Open the bonnet and wait"],"Pull over, switch off the engine, put hazard lights on, and get out. Use an emergency exit and call for help from an emergency telephone."],
["IN","When may you use hazard warning lights while moving?",["On a motorway, to warn of a hazard ahead","When you are driving slowly in fog","When you are looking for a parking space","When you are being towed on any road, always"],"While driving you may use them only briefly on a motorway or unrestricted dual carriageway to warn traffic behind of a hazard or obstruction ahead."],
["IN","Your tyre bursts while you are driving. What should you do?",["Grip the wheel firmly and let the car roll to a stop","Brake as hard as possible at once to stop before the tyre shreds","Steer sharply to the verge","Change down and accelerate"],"Hold the steering wheel firmly, do not brake hard, and let the car slow gradually before pulling up at the side of the road."],
["IN","A lorry involved in a crash is showing an orange hazard plate. Why does that matter?",["It tells the emergency services what dangerous goods it carries","It warns other drivers that the lorry is carrying an overweight load","It means the lorry is foreign-registered","It shows the driver is a trainee"],"Hazard plates identify the dangerous substance on board. Keep well away, and pass the information on when you call the emergency services."],
["IN","Your engine catches fire. What should you NOT do?",["Open the bonnet","Get everyone out","Call the fire service","Move well away from the car"],"Opening the bonnet feeds the fire with air and it can flare up at you. Get everyone out and away, and call the fire service."],

// ---------- Vehicle loading
["LO","Who is responsible for making sure a vehicle is not overloaded?",["The driver","The owner","The person who loaded it","The passengers"],"The driver is always responsible for the load: its weight, how it is secured and how it is spread."],
["LO","Your caravan starts to snake from side to side. What should you do?",["Ease off the accelerator and slow down gradually","Brake hard","Accelerate to pull it straight","Steer sharply against each swing until the caravan settles"],"Ease off gently and let the speed fall. Braking hard or steering sharply makes snaking worse."],
["LO","How does a heavy load on a roof rack affect your car?",["It makes the car less stable","It improves cornering","It shortens the braking distance","It makes the steering lighter and safer"],"Weight carried high up raises the centre of gravity. The car leans more in corners and is more affected by wind."],
["LO","You are carrying a heavy load in the boot. What may you need to adjust?",["Tyre pressures and headlight aim","The door mirrors and the interior mirror only","The seat height","The radio aerial"],"A heavy load needs higher tyre pressures, as given in the handbook, and it tilts the car back so the headlights may need lowering to avoid dazzling others."],
["LO","How should a dog be carried in a car?",["Restrained with a harness or carrier","Loose on the back seat","On a passenger's lap in the front","With its head out of an open window"],"Animals must be restrained so they cannot distract you or be thrown forward and injure you or themselves in a sudden stop."],
["LO","Where should the heaviest items go when you load a trailer or caravan?",["Low down and over the axle","At the very back","As high as possible","All on one side"],"Keeping heavy items low and near the axle keeps the outfit stable. Too much weight at the back encourages snaking."],
["LO","What is the purpose of a breakaway cable on a braked trailer?",["It applies the trailer's brakes if it comes loose","It carries power from the car to the trailer's lights and brakes","It stops the trailer being stolen","It stops the trailer snaking"],"If the trailer becomes detached, the breakaway cable pulls on its brakes before snapping, so the trailer stops."],
["LO","A load sticks out from the back of your car. What must you make sure of?",["It is secure and clearly visible to others","It is painted white","It is lower than the bumper","It rests on the bumper and covers only part of the number plate"],"Any load must be secure and must not stick out dangerously. Overhanging loads need to be clearly marked so others can see them."],
["LO","What can overloading your vehicle seriously affect?",["Steering and braking","The radio reception","The windscreen wipers","The colour of the exhaust smoke only"],"Too much weight makes steering less precise and stopping distances longer, and it can overheat tyres."],
["LO","Can you carry a passenger in a caravan while it is being towed?",["No","Yes, if they are seated","Yes, if they are over 14","Yes, on a motorway only"],"Nobody may travel in a towed caravan. It has no crash protection and they could be seriously hurt."]
];
